  '[{"id":"p1","category":"Essentials","item":"Passport & Japan Rail Pass voucher","packed":true},{"id":"p2","category":"Electronics","item":"Portable Power Bank (10,000mAh)","packed":true},{"id":"p3","category":"Clothing","item":"Comfortable Walking Shoes (15k steps/day)","packed":true},{"id":"p4","category":"Documents","item":"Suica/Pasmo Card on Apple Wallet","packed":false},{"id":"p5","category":"Toiletries","item":"Compact Folding Umbrella","packed":false}]'::jsonb,
  '[{"dayNumber":1,"title":"Arrival & Shibuya Crossing Spectacle","activities":[{"id":"act_1_1","title":"Hotel Check-in & Rest in Shinjuku","category":"Hotel","location":"Shinjuku, Tokyo","description":"Settle into your hotel, get fresh, and pick up your pocket Wi-Fi router.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":35.6938,"lng":139.7034,"googleMapsUrl":"https://maps.google.com/?q=Shinjuku+Tokyo"},{"id":"act_1_2","title":"Meiji Jingu Shrine & Harajuku Takeshita Street","category":"History","location":"Shibuya City, Tokyo","description":"Stroll through serene forest paths to the majestic Shinto shrine, then walk down vibrant Takeshita Street for quirky street food.","estimatedDuration":"3 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":35.6764,"lng":139.6993,"googleMapsUrl":"https://maps.google.com/?q=Meiji+Jingu"},{"id":"act_1_3","title":"Shibuya Scramble Crossing & Shibuya Sky Sunset","category":"City","location":"Shibuya, Tokyo","description":"Cross the busiest intersection on earth and head up to Shibuya Sky open-air observation deck for a panoramic 360° night view.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":35.6595,"lng":139.7004,"googleMapsUrl":"https://maps.google.com/?q=Shibuya+Sky"}]},{"dayNumber":2,"title":"Historic Asakusa & Futuristic Odaiba","activities":[{"id":"act_2_1","title":"Senso-ji Temple & Nakamise Shopping Street","category":"Museum","location":"Asakusa, Tokyo","description":"Explore Tokyo’s oldest Buddhist temple, smell the incense, and try traditional matcha snacks.","estimatedDuration":"2.5 hrs","estimatedCost":10,"timeOfDay":"Morning","lat":35.7148,"lng":139.7967,"googleMapsUrl":"https://maps.google.com/?q=Sensoji+Temple"},{"id":"act_2_2","title":"Tokyo Skytree Observation & Lunch","category":"City","location":"Sumida, Tokyo","description":"Ascend Japan’s tallest structure and enjoy a delicious tonkatsu lunch at Solamachi Mall.","estimatedDuration":"2 hrs","estimatedCost":35,"timeOfDay":"Afternoon","lat":35.7101,"lng":139.8107,"googleMapsUrl":"https://maps.google.com/?q=Tokyo+Skytree"},{"id":"act_2_3","title":"TeamLab Planets Digital Art Museum","category":"Museum","location":"Toyosu, Tokyo","description":"Walk through water and immersive light projection rooms in this iconic world-class digital art sanctuary.","estimatedDuration":"2 hrs","estimatedCost":32,"timeOfDay":"Evening","lat":35.6491,"lng":139.7898,"googleMapsUrl":"https://maps.google.com/?q=TeamLab+Planets"}]},{"dayNumber":3,"title":"Ueno Museums & Akihabara Electric Town","activities":[{"id":"act_3_1","title":"Ueno Park & Tokyo National Museum","category":"Museum","location":"Ueno, Tokyo","description":"Wander the leafy park and see samurai armor, katana, and ukiyo-e prints in Japan’s oldest museum.","estimatedDuration":"3 hrs","estimatedCost":8,"timeOfDay":"Morning","lat":35.7188,"lng":139.7765,"googleMapsUrl":"https://maps.google.com/?q=Tokyo+National+Museum"},{"id":"act_3_2","title":"Ameyoko Market Street Food Lunch","category":"Food","location":"Ueno, Tokyo","description":"Graze on grilled seafood skewers, fresh fruit, and takoyaki along this lively post-war market alley.","estimatedDuration":"1.5 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":35.7101,"lng":139.7745,"googleMapsUrl":"https://maps.google.com/?q=Ameyoko+Market"},{"id":"act_3_3","title":"Akihabara Anime Shops & Retro Arcades","category":"Anime","location":"Akihabara, Tokyo","description":"Dive into multi-story manga stores, capsule-toy walls, and retro game arcades under glowing neon signs.","estimatedDuration":"3 hrs","estimatedCost":40,"timeOfDay":"Evening","lat":35.6984,"lng":139.7731,"googleMapsUrl":"https://maps.google.com/?q=Akihabara"}]},{"dayNumber":4,"title":"Tsukiji Breakfast, Ginza Glamour & Tokyo Tower","activities":[{"id":"act_4_1","title":"Tsukiji Outer Market Sushi Breakfast","category":"Food","location":"Tsukiji, Tokyo","description":"Start early with ultra-fresh sushi, tamagoyaki omelette, and matcha at the legendary outer market stalls.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Morning","lat":35.6655,"lng":139.7707,"googleMapsUrl":"https://maps.google.com/?q=Tsukiji+Outer+Market"},{"id":"act_4_2","title":"Ginza Flagship Stores & Kabuki-za","category":"Shopping","location":"Ginza, Tokyo","description":"Browse luxury flagships and the Itoya stationery tower, then catch a single act of kabuki theatre.","estimatedDuration":"3.5 hrs","estimatedCost":25,"timeOfDay":"Afternoon","lat":35.6717,"lng":139.765,"googleMapsUrl":"https://maps.google.com/?q=Ginza+Tokyo"},{"id":"act_4_3","title":"Tokyo Tower Night Views & Zojo-ji Temple","category":"City","location":"Minato, Tokyo","description":"See the illuminated orange tower rise behind the ancient Zojo-ji temple gate, then ride up for city lights.","estimatedDuration":"2 hrs","estimatedCost":12,"timeOfDay":"Evening","lat":35.6586,"lng":139.7454,"googleMapsUrl":"https://maps.google.com/?q=Tokyo+Tower"}]},{"dayNumber":5,"title":"Hakone Day Trip: Hot Springs & Mt. Fuji Views","activities":[{"id":"act_5_1","title":"Romancecar Train to Hakone & Lake Ashi Cruise","category":"Nature","location":"Hakone, Kanagawa","description":"Ride the scenic express from Shinjuku, then sail Lake Ashi on a pirate ship with Mt. Fuji on clear days.","estimatedDuration":"3 hrs","estimatedCost":55,"timeOfDay":"Morning","lat":35.2048,"lng":139.0246,"googleMapsUrl":"https://maps.google.com/?q=Lake+Ashi"},{"id":"act_5_2","title":"Owakudani Volcanic Valley Ropeway","category":"Adventure","location":"Hakone, Kanagawa","description":"Glide over steaming sulfur vents and taste the famous black eggs said to add seven years to your life.","estimatedDuration":"2 hrs","estimatedCost":20,"timeOfDay":"Afternoon","lat":35.2443,"lng":139.0197,"googleMapsUrl":"https://maps.google.com/?q=Owakudani"},{"id":"act_5_3","title":"Onsen Soak at Tenzan Tohji-kyo","category":"Nature","location":"Yumoto, Hakone","description":"Unwind in open-air hot spring pools set in the forest before the train back to Tokyo.","estimatedDuration":"2 hrs","estimatedCost":15,"timeOfDay":"Evening","lat":35.2269,"lng":139.092,"googleMapsUrl":"https://maps.google.com/?q=Tenzan+Tohji-kyo"}]},{"dayNumber":6,"title":"Ghibli Magic & Shimokitazawa Vintage","activities":[{"id":"act_6_1","title":"Ghibli Museum, Mitaka","category":"Anime","location":"Mitaka, Tokyo","description":"Step into Hayao Miyazaki’s whimsical world with exclusive short films and the rooftop Laputa robot.","estimatedDuration":"2.5 hrs","estimatedCost":8,"timeOfDay":"Morning","lat":35.6962,"lng":139.5704,"googleMapsUrl":"https://maps.google.com/?q=Ghibli+Museum"},{"id":"act_6_2","title":"Inokashira Park Boat Ride","category":"Nature","location":"Kichijoji, Tokyo","description":"Paddle a swan boat across the pond and grab yakitori at the famous Iseya stall nearby.","estimatedDuration":"1.5 hrs","estimatedCost":12,"timeOfDay":"Afternoon","lat":35.6997,"lng":139.5728,"googleMapsUrl":"https://maps.google.com/?q=Inokashira+Park"},{"id":"act_6_3","title":"Shimokitazawa Thrift Shops & Live Music Bars","category":"Nightlife","location":"Shimokitazawa, Tokyo","description":"Hunt for vintage jackets and vinyl, then catch an indie gig in a tiny basement live house.","estimatedDuration":"3 hrs","estimatedCost":35,"timeOfDay":"Evening","lat":35.6614,"lng":139.668,"googleMapsUrl":"https://maps.google.com/?q=Shimokitazawa"}]},{"dayNumber":7,"title":"Imperial Gardens & Golden Gai Farewell","activities":[{"id":"act_7_1","title":"Imperial Palace East Gardens","category":"History","location":"Chiyoda, Tokyo","description":"Walk among stone walls and moats of the former Edo Castle, now a peaceful public garden.","estimatedDuration":"2 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":35.6852,"lng":139.7528,"googleMapsUrl":"https://maps.google.com/?q=Imperial+Palace+East+Gardens"},{"id":"act_7_2","title":"Shinjuku Gyoen National Garden","category":"Nature","location":"Shinjuku, Tokyo","description":"Picnic beneath cherry trees in a garden blending Japanese, French, and English landscape styles.","estimatedDuration":"2 hrs","estimatedCost":4,"timeOfDay":"Afternoon","lat":35.6852,"lng":139.71,"googleMapsUrl":"https://maps.google.com/?q=Shinjuku+Gyoen"},{"id":"act_7_3","title":"Omoide Yokocho & Golden Gai Bar Hop","category":"Nightlife","location":"Shinjuku, Tokyo","description":"Toast your final night in smoky yakitori alleys and pocket-sized bars seating just six guests.","estimatedDuration":"3 hrs","estimatedCost":50,"timeOfDay":"Evening","lat":35.6938,"lng":139.7036,"googleMapsUrl":"https://maps.google.com/?q=Golden+Gai"}]}]'::jsonb,
  '[{"id":"c1","userId":"user_maya","userName":"Maya Lin","userAvatar":"https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=200&q=80","content":"Followed this itinerary last week! The ramen recommendation in Shinjuku was mind-blowing.","rating":5,"createdAt":"3 days ago"},{"id":"c2","userId":"user_david","userName":"David Miller","userAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","content":"Pro tip: book the TeamLab Planets tickets at least 3 weeks in advance. Awesome guide!","rating":5,"createdAt":"5 days ago"}]'::jsonb,
