-- 5 Days in Paris: Art, Gastronomy & Seine River Romance
update public.travel_plans set
  destination = 'Paris',
  country = 'France',
  flag_emoji = '🇫🇷',
  cover_image = 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1200&q=80',
  summary = 'Soak in the timeless elegance of Paris with Louvre museum passes, Montmartre artists plazas, freshly baked croissants, and an evening sunset cruise along the Seine.',
  duration_days = 5,
  season = 'Spring',
  preferences = '["Museum","Romantic","Architecture","Food","Cafe"]'::jsonb,
  companion_style = 'Couple',
  estimated_cost_usd = 1650,
  transportation = 'Paris Metro Day Pass & Walking',
  weather_forecast = 'Mild & Sunny 16°C (61°F) with light breeze',
  packing_list = '[{"id":"pp1","category":"Clothing","item":"Stylish Trench Coat & Scarf","packed":true},{"id":"pp2","category":"Essentials","item":"Museum Pass 4-day ticket","packed":true},{"id":"pp3","category":"Clothing","item":"Comfortable Leather Walking Shoes","packed":false}]'::jsonb,
  days = '[{"dayNumber":1,"title":"Monuments of Light & Eiffel Tower Sparkle","activities":[{"id":"pact_1","title":"Louvre Museum Masterpieces Tour","category":"Museum","location":"1st Arrondissement, Paris","description":"Marvel at the Mona Lisa, Venus de Milo, and Winged Victory of Samothrace in the world’s largest art museum.","estimatedDuration":"3 hrs","estimatedCost":22,"timeOfDay":"Morning","lat":48.8606,"lng":2.3376,"googleMapsUrl":"https://maps.google.com/?q=Louvre+Museum"},{"id":"pact_2","title":"Tuileries Garden Picnic & Cafe de Flore Lunch","category":"Cafe","location":"Saint-Germain-des-Prés, Paris","description":"Enjoy fresh baguette, brie cheese, and macaroons in Tuileries before sipping coffee at classic Parisian cafes.","estimatedDuration":"2.5 hrs","estimatedCost":35,"timeOfDay":"Afternoon","lat":48.8634,"lng":2.3275,"googleMapsUrl":"https://maps.google.com/?q=Tuileries+Garden"},{"id":"pact_3","title":"Trocadéro View & Eiffel Tower Light Show","category":"Romantic","location":"7th Arrondissement, Paris","description":"Watch the Eiffel Tower light up in sparkling diamonds at the turn of every hour.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Evening","lat":48.8584,"lng":2.2945,"googleMapsUrl":"https://maps.google.com/?q=Eiffel+Tower"}]},{"dayNumber":2,"title":"Montmartre Artists & Sacré-Cœur Sunset","activities":[{"id":"pact_4","title":"Boulangerie Breakfast & Rue Cler Market","category":"Food","location":"7th Arrondissement, Paris","description":"Grab warm croissants and pain au chocolat, then browse cheese, fruit, and flower stalls on a classic market street.","estimatedDuration":"1.5 hrs","estimatedCost":15,"timeOfDay":"Morning","lat":48.8565,"lng":2.306,"googleMapsUrl":"https://maps.google.com/?q=Rue+Cler"},{"id":"pact_5","title":"Place du Tertre Painters & Montmartre Lanes","category":"Hidden Gems","location":"Montmartre, Paris","description":"Watch portrait artists at work and wander cobbled lanes past the Moulin de la Galette windmill.","estimatedDuration":"3 hrs","estimatedCost":20,"timeOfDay":"Afternoon","lat":48.8865,"lng":2.3408,"googleMapsUrl":"https://maps.google.com/?q=Place+du+Tertre"},{"id":"pact_6","title":"Sacré-Cœur Steps Sunset & Bistro Dinner","category":"Romantic","location":"Montmartre, Paris","description":"Watch the city turn gold from the basilica steps, then share coq au vin in a candlelit bistro.","estimatedDuration":"3 hrs","estimatedCost":70,"timeOfDay":"Evening","lat":48.8867,"lng":2.3431,"googleMapsUrl":"https://maps.google.com/?q=Sacre+Coeur"}]},{"dayNumber":3,"title":"Impressionists & a Seine River Cruise","activities":[{"id":"pact_7","title":"Musée d’Orsay Impressionist Galleries","category":"Museum","location":"7th Arrondissement, Paris","description":"See Monet, Renoir, and Van Gogh inside a grand Beaux-Arts railway station with a giant clock window.","estimatedDuration":"3 hrs","estimatedCost":18,"timeOfDay":"Morning","lat":48.86,"lng":2.3266,"googleMapsUrl":"https://maps.google.com/?q=Musee+d+Orsay"},{"id":"pact_8","title":"Saint-Germain Cafés & Luxembourg Gardens","category":"Cafe","location":"6th Arrondissement, Paris","description":"Linger over café crème at Les Deux Magots, then stroll among fountains and green chairs in the Luxembourg Gardens.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Afternoon","lat":48.8462,"lng":2.3372,"googleMapsUrl":"https://maps.google.com/?q=Jardin+du+Luxembourg"},{"id":"pact_9","title":"Seine Sunset Cruise","category":"Romantic","location":"Pont Neuf, Paris","description":"Glide past Notre-Dame, the Louvre, and the Eiffel Tower as the bridges light up at dusk.","estimatedDuration":"1.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":48.8577,"lng":2.341,"googleMapsUrl":"https://maps.google.com/?q=Vedettes+du+Pont+Neuf"}]},{"dayNumber":4,"title":"Versailles Day Trip","activities":[{"id":"pact_10","title":"Palace of Versailles & Hall of Mirrors","category":"History","location":"Versailles, France","description":"Tour the opulent royal apartments and the dazzling Hall of Mirrors where the WWI treaty was signed.","estimatedDuration":"3 hrs","estimatedCost":21,"timeOfDay":"Morning","lat":48.8049,"lng":2.1204,"googleMapsUrl":"https://maps.google.com/?q=Palace+of+Versailles"},{"id":"pact_11","title":"Versailles Gardens by Bike & Marie Antoinette’s Hamlet","category":"Nature","location":"Versailles, France","description":"Rent bikes to cruise the Grand Canal and discover the queen’s storybook rustic village.","estimatedDuration":"3 hrs","estimatedCost":25,"timeOfDay":"Afternoon","lat":48.8159,"lng":2.1092,"googleMapsUrl":"https://maps.google.com/?q=Hameau+de+la+Reine"},{"id":"pact_12","title":"Dinner in Le Marais","category":"Food","location":"Le Marais, Paris","description":"Back in the city, enjoy falafel on Rue des Rosiers or a natural-wine bistro in this historic quarter.","estimatedDuration":"2 hrs","estimatedCost":45,"timeOfDay":"Evening","lat":48.8575,"lng":2.3592,"googleMapsUrl":"https://maps.google.com/?q=Le+Marais"}]},{"dayNumber":5,"title":"Île de la Cité & Farewell Views","activities":[{"id":"pact_13","title":"Sainte-Chapelle Stained Glass","category":"Architecture","location":"Île de la Cité, Paris","description":"Be bathed in color from 1,113 stained-glass panels in this Gothic jewel box chapel.","estimatedDuration":"1.5 hrs","estimatedCost":13,"timeOfDay":"Morning","lat":48.8554,"lng":2.345,"googleMapsUrl":"https://maps.google.com/?q=Sainte-Chapelle"},{"id":"pact_14","title":"Shakespeare and Company & Latin Quarter","category":"Hidden Gems","location":"5th Arrondissement, Paris","description":"Browse the legendary English bookshop facing Notre-Dame and lunch on crepes in the Latin Quarter.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Afternoon","lat":48.8526,"lng":2.3471,"googleMapsUrl":"https://maps.google.com/?q=Shakespeare+and+Company"},{"id":"pact_15","title":"Arc de Triomphe Rooftop & Champs-Élysées","category":"City","location":"8th Arrondissement, Paris","description":"Climb to the rooftop for a starburst view of avenues, then stroll the illuminated Champs-Élysées.","estimatedDuration":"2 hrs","estimatedCost":16,"timeOfDay":"Evening","lat":48.8738,"lng":2.295,"googleMapsUrl":"https://maps.google.com/?q=Arc+de+Triomphe"}]}]'::jsonb,
