st":110,"timeOfDay":"Afternoon","lat":63.5321,"lng":-19.5114,"googleMapsUrl":"https://maps.google.com/?q=Skogafoss"},{"id":"iact_6","title":"Reynisfjara Black Sand Beach at Dusk","category":"Photography","location":"Vík, Iceland","description":"Photograph basalt columns and sea stacks — keep well back from the powerful sneaker waves.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Evening","lat":63.4045,"lng":-19.045,"googleMapsUrl":"https://maps.google.com/?q=Reynisfjara"}]},{"dayNumber":3,"title":"Glacier Lagoon & Diamond Beach","activities":[{"id":"iact_7","title":"Fjaðrárgljúfur Canyon Rim Trail","category":"Hiking","location":"Kirkjubæjarklaustur, Iceland","description":"Walk the mossy rim of a serpentine canyon carved by glacial meltwater.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":63.7714,"lng":-18.1717,"googleMapsUrl":"https://maps.google.com/?q=Fjadrargljufur"},{"id":"iact_8","title":"Jökulsárlón Glacier Lagoon Amphibian Boat","category":"Adventure","location":"Vatnajökull, Iceland","description":"Cruise among floating blue icebergs and spot seals lounging on the floes.","estimatedDuration":"2 hrs","estimatedCost":75,"timeOfDay":"Afternoon","lat":64.0784,"lng":-16.2306,"googleMapsUrl":"https://maps.google.com/?q=Jokulsarlon"},{"id":"iact_9","title":"Diamond Beach Ice Sculptures","category":"Photography","location":"Breiðamerkursandur, Iceland","description":"Shoot glittering ice chunks washed up on jet-black sand as the sun goes down.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Evening","lat":64.0443,"lng":-16.1777,"googleMapsUrl":"https://maps.google.com/?q=Diamond+Beach+Iceland"}]},{"dayNumber":4,"title":"Eastfjords Scenic Drive","activities":[{"id":"iact_10","title":"Vestrahorn Mountain & Stokksnes Viking Village","category":"Photography","location":"Höfn, Iceland","description":"Capture jagged peaks reflected in black dunes beside a replica Viking film set.","estimatedDuration":"2 hrs","e