  days = '[{"dayNumber":1,"title":"Grand Palace & Riverside Temples","activities":[{"id":"bact_1","title":"Grand Palace & Wat Phra Kaew","category":"History","location":"Phra Nakhon, Bangkok","description":"Marvel at the dazzling royal complex and the revered Emerald Buddha — arrive at opening to beat the heat.","estimatedDuration":"2.5 hrs","estimatedCost":15,"timeOfDay":"Morning","lat":13.75,"lng":100.4913,"googleMapsUrl":"https://maps.google.com/?q=Grand+Palace+Bangkok"},{"id":"bact_2","title":"Wat Pho Reclining Buddha & Thai Massage","category":"History","location":"Phra Nakhon, Bangkok","description":"See the 46-meter golden reclining Buddha, then get a traditional massage at the temple’s own school.","estimatedDuration":"2.5 hrs","estimatedCost":25,"timeOfDay":"Afternoon","lat":13.7465,"lng":100.4927,"googleMapsUrl":"https://maps.google.com/?q=Wat+Pho"},{"id":"bact_3","title":"Wat Arun Sunset from the River","category":"Photography","location":"Bangkok Yai, Bangkok","description":"Take the cross-river ferry and watch the porcelain-studded Temple of Dawn glow at sunset.","estimatedDuration":"2 hrs","estimatedCost":5,"timeOfDay":"Evening","lat":13.7437,"lng":100.4889,"googleMapsUrl":"https://maps.google.com/?q=Wat+Arun"}]},{"dayNumber":2,"title":"Floating Market & Chinatown Food Crawl","activities":[{"id":"bact_4","title":"Damnoen Saduak Floating Market","category":"Food","location":"Ratchaburi, Thailand","description":"Ride a longtail boat through canals packed with vendors selling boat noodles and mango sticky rice.","estimatedDuration":"4 hrs","estimatedCost":35,"timeOfDay":"Morning","lat":13.5196,"lng":99.959,"googleMapsUrl":"https://maps.google.com/?q=Damnoen+Saduak+Floating+Market"},{"id":"bact_5","title":"Jim Thompson House Museum","category":"Museum","location":"Pathum Wan, Bangkok","description":"Explore the teak-house home of the American silk tycoon who vanished mysteriously in 1967.","estimatedDuration":"1.5 hrs","estimatedCost":6,"timeOfDay":"Aftern