  days = '[{"dayNumber":1,"title":"Marina Bay & Gardens by the Bay","activities":[{"id":"sact_1","title":"Merlion Park & Marina Bay Waterfront","category":"City","location":"Marina Bay, Singapore","description":"Snap photos with the half-lion, half-fish icon against the Marina Bay Sands skyline.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":1.2868,"lng":103.8545,"googleMapsUrl":"https://maps.google.com/?q=Merlion+Park"},{"id":"sact_2","title":"Cloud Forest & Flower Dome","category":"Nature","location":"Gardens by the Bay, Singapore","description":"Explore a misty indoor mountain with the world’s tallest indoor waterfall, then the cool Flower Dome.","estimatedDuration":"3 hrs","estimatedCost":40,"timeOfDay":"Afternoon","lat":1.2816,"lng":103.8636,"googleMapsUrl":"https://maps.google.com/?q=Cloud+Forest+Singapore"},{"id":"sact_3","title":"Satay by the Bay & Garden Rhapsody Show","category":"Food","location":"Gardens by the Bay, Singapore","description":"Feast on satay skewers, then lie back under the Supertrees for the free light-and-music show.","estimatedDuration":"2.5 hrs","estimatedCost":25,"timeOfDay":"Evening","lat":1.2823,"lng":103.8684,"googleMapsUrl":"https://maps.google.com/?q=Supertree+Grove"}]},{"dayNumber":2,"title":"Heritage Neighborhoods & Night Safari","activities":[{"id":"sact_4","title":"Chinatown & Buddha Tooth Relic Temple","category":"History","location":"Chinatown, Singapore","description":"Wander shophouse streets and visit the ornate five-story temple housing a sacred relic.","estimatedDuration":"2 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":1.2814,"lng":103.8443,"googleMapsUrl":"https://maps.google.com/?q=Buddha+Tooth+Relic+Temple"},{"id":"sact_5","title":"Maxwell Hawker Centre Lunch","category":"Food","location":"Chinatown, Singapore","description":"Queue for the legendary Tian Tian Hainanese chicken rice — a full meal for under $6.","estimatedDuration":"1 hr","estimatedCost":10,"timeOfDay":"Afternoon","l