ry+London"},{"id":"lact_6","title":"West End Musical in Covent Garden","category":"Nightlife","location":"Covent Garden, London","description":"Catch a blockbuster musical after pre-theatre dinner in the piazza.","estimatedDuration":"3.5 hrs","estimatedCost":95,"timeOfDay":"Evening","lat":51.5117,"lng":-0.124,"googleMapsUrl":"https://maps.google.com/?q=Covent+Garden"}]},{"dayNumber":3,"title":"Tower, Borough Market & Sky Garden","activities":[{"id":"lact_7","title":"Tower of London & Crown Jewels","category":"History","location":"Tower Hill, London","description":"Join a Beefeater tour of the 1,000-year-old fortress and gaze at the glittering Crown Jewels.","estimatedDuration":"3 hrs","estimatedCost":40,"timeOfDay":"Morning","lat":51.5081,"lng":-0.0759,"googleMapsUrl":"https://maps.google.com/?q=Tower+of+London"},{"id":"lact_8","title":"Borough Market Grazing Lunch","category":"Food","location":"Southwark, London","description":"Cross Tower Bridge and snack on raclette, scotch eggs, and doughnuts at London’s oldest food market.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Afternoon","lat":51.5055,"lng":-0.091,"googleMapsUrl":"https://maps.google.com/?q=Borough+Market"},{"id":"lact_9","title":"Sky Garden Sunset Drinks","category":"Romantic","location":"City of London, London","description":"Sip cocktails in a free rooftop jungle 35 floors above the financial district (book ahead).","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Evening","lat":51.5113,"lng":-0.0835,"googleMapsUrl":"https://maps.google.com/?q=Sky+Garden+London"}]},{"dayNumber":4,"title":"Kensington, Hyde Park & Notting Hill","activities":[{"id":"lact_10","title":"Natural History Museum","category":"Museum","location":"South Kensington, London","description":"Stand beneath the blue whale skeleton in a cathedral-like Victorian hall.","estimatedDuration":"2.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":51.4967,"lng":-0.1764,"googleMapsUrl":"https://maps.google.com/?q=Natural+History+Museum+London"},{"id":"lact_11","title":"Hyde Park & Kensington Palace Gardens","category":"Nature","location":"Hyde Park, London","description":"Rent a pedalo on the Serpentine and stroll to Princess Diana’s former home.","estimatedDuration":"2.5 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":51.5073,"lng":-0.1657,"googleMapsUrl":"https://maps.google.com/?q=Hyde+Park"},{"id":"lact_12","title":"Notting Hill Pastel Streets & Gastropub Dinner","category":"Food","location":"Notting Hill, London","description":"Photograph the colorful terraces of Portobello Road, then dine on Sunday-roast-style pub classics.","estimatedDuration":"2.5 hrs","estimatedCost":50,"timeOfDay":"Evening","lat":51.5155,"lng":-0.205,"googleMapsUrl":"https://maps.google.com/?q=Portobello+Road"}]},{"dayNumber":5,"title":"Greenwich & East London Vibes","activities":[{"id":"lact_13","title":"Thames Clipper to Greenwich & Royal Observatory","category":"History","location":"Greenwich, London","description":"Ride the river boat, then stand astride the Prime Meridian line at 0° longitude.","estimatedDuration":"3 hrs","estimatedCost":30,"timeOfDay":"Morning","lat":51.4769,"lng":-0.0005,"googleMapsUrl":"https://maps.google.com/?q=Royal+Observatory+Greenwich"},{"id":"lact_14","title":"Shoreditch Street Art & Brick Lane","category":"Hidden Gems","location":"Shoreditch, London","description":"Hunt for Banksy-era murals and grab a salt-beef bagel from the 24-hour Brick Lane bakery.","estimatedDuration":"2.5 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":51.5219,"lng":-0.0717,"googleMapsUrl":"https://maps.google.com/?q=Brick+Lane"},{"id":"lact_15","title":"Farewell Dinner in Soho","category":"Nightlife","location":"Soho, London","description":"Toast the trip with small plates and a cocktail in London’s liveliest late-night district.","estimatedDuration":"3 hrs","estimatedCost":70,"timeOfDay":"Evening","lat":51.5136,"lng":-0.1365,"googleMapsUrl":"https://maps.google.com/?q=Soho+London"}]}]'::jsonb,
