-- 4 Days in New York City: The Ultimate First-Timer Guide
update public.travel_plans set
  destination = 'New York City',
  country = 'United States',
  flag_emoji = '🇺🇸',
  cover_image = 'https://images.unsplash.com/photo-1534430480872-3498386e7856?auto=format&fit=crop&w=1200&q=80',
  summary = 'Skyline views, Central Park, the Met, Brooklyn Bridge at sunrise, dollar-slice pizza, and a Broadway show — a solo-friendly whirlwind of NYC icons.',
  duration_days = 4,
  season = 'Autumn',
  preferences = '["City","Food","Museum","Architecture","Nightlife"]'::jsonb,
  companion_style = 'Solo',
  estimated_cost_usd = 1500,
  transportation = 'Subway with OMNY tap-to-pay & lots of walking',
  weather_forecast = 'Crisp Autumn 16°C (61°F), sunny with fall foliage',
  packing_list = '[{"id":"np1","category":"Clothing","item":"Broken-in sneakers (20k steps a day)","packed":true},{"id":"np2","category":"Electronics","item":"Phone with OMNY / Apple Pay set up","packed":true},{"id":"np3","category":"Clothing","item":"Light jacket for windy evenings","packed":false}]'::jsonb,
  days = '[{"dayNumber":1,"title":"Midtown Icons & Times Square","activities":[{"id":"nact_1","title":"Top of the Rock Observation Deck","category":"City","location":"Midtown, Manhattan","description":"Get the classic skyline view with the Empire State Building framed in front of you.","estimatedDuration":"1.5 hrs","estimatedCost":45,"timeOfDay":"Morning","lat":40.7593,"lng":-73.9794,"googleMapsUrl":"https://maps.google.com/?q=Top+of+the+Rock"},{"id":"nact_2","title":"Grand Central, Bryant Park & NY Public Library","category":"Architecture","location":"Midtown, Manhattan","description":"Whisper in the Whispering Gallery and admire the library’s Rose Main Reading Room.","estimatedDuration":"2.5 hrs","estimatedCost":0,"timeOfDay":"Afternoon","lat":40.7527,"lng":-73.9772,"googleMapsUrl":"https://maps.google.com/?q=Grand+Central+Terminal"},{"id":"nact_3","title":"Broadway Show & Times Square Lights","category":"Nightlife","location":"Theater District, Manhattan","description":"Grab TKTS discount seats for a Broadway show, then soak in the neon chaos.","estimatedDuration":"3.5 hrs","estimatedCost":120,"timeOfDay":"Evening","lat":40.758,"lng":-73.9855,"googleMapsUrl":"https://maps.google.com/?q=Times+Square"}]},{"dayNumber":2,"title":"Central Park & Museum Mile","activities":[{"id":"nact_4","title":"Central Park Bike Loop","category":"Nature","location":"Central Park, Manhattan","description":"Cycle past Bethesda Fountain, Bow Bridge, and Strawberry Fields on the 6-mile loop.","estimatedDuration":"2.5 hrs","estimatedCost":25,"timeOfDay":"Morning","lat":40.7736,"lng":-73.9712,"googleMapsUrl":"https://maps.google.com/?q=Bethesda+Fountain"},{"id":"nact_5","title":"The Metropolitan Museum of Art","category":"Museum","location":"Upper East Side, Manhattan","description":"See the Temple of Dendur, armor hall, and rooftop garden views of the park.","estimatedDuration":"3 hrs","estimatedCost":30,"timeOfDay":"Afternoon","lat":40.7794,"lng":-73.9632,"googleMapsUrl":"https://maps.google.com/?q=Metropolitan+Museum+of+Art"},{"id":"nact_6","title":"Jazz Night in Harlem","category":"Nightlife","location":"Harlem, Manhattan","description":"Eat soul food and catch live jazz in the neighborhood that shaped American music.","estimatedDuration":"3 hrs","estimatedCost":55,"timeOfDay":"Evening","lat":40.8116,"lng":-73.9465,"googleMapsUrl":"https://maps.google.com/?q=Minton%27s+Playhouse"}]},{"dayNumber":3,"title":"Lower Manhattan & Brooklyn","activities":[{"id":"nact_7","title":"Statue of Liberty Ferry & Ellis Island","category":"History","location":"Liberty Island, New York","description":"Sail to Lady Liberty and trace immigrant stories at the Ellis Island museum.","estimatedDuration":"4 hrs","estimatedCost":25,"timeOfDay":"Morning","lat":40.6892,"lng":-74.0445,"googleMapsUrl":"https://maps.google.com/?q=Statue+of+Liberty"},{"id":"nact_8","title":"9/11 Memorial & One World Observatory","category":"History","location":"Financial District, Manhattan","description":"Pay respects at the reflecting pools, then ride to the top of the Western Hemisphere’s tallest building.","estimatedDuration":"2.5 hrs","estimatedCost":45,"timeOfDay":"Afternoon","lat":40.7115,"lng":-74.0134,"googleMapsUrl":"https://maps.google.com/?q=9/11+Memorial"},{"id":"nact_9","title":"Brooklyn Bridge Walk & DUMBO Pizza","category":"Food","location":"DUMBO, Brooklyn","description":"Walk the bridge at golden hour and end with coal-fired pizza beside the Manhattan Bridge view.","estimatedDuration":"2.5 hrs","estimatedCost":30,"timeOfDay":"Evening","lat":40.7033,"lng":-73.9881,"googleMapsUrl":"https://maps.google.com/?q=DUMBO+Brooklyn"}]},{"dayNumber":4,"title":"High Line, Chelsea & Village Farewell","activities":[{"id":"nact_10","title":"The High Line Elevated Park","category":"Nature","location":"Chelsea, Manhattan","description":"Stroll a former freight rail line turned garden walkway ending at Hudson Yards’ Vessel.","estimatedDuration":"2 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":40.748,"lng":-74.0048,"googleMapsUrl":"https://maps.google.com/?q=The+High+Line"},{"id":"nact_11","title":"Chelsea Market Food Hall Lunch","category":"Food","location":"Meatpacking District, Manhattan","description":"Graze on lobster rolls, tacos, and fresh-baked brownies in an old Nabisco factory.","estimatedDuration":"1.5 hrs","estimatedCost":30,"timeOfDay":"Afternoon","lat":40.7424,"lng":-74.0061,"googleMapsUrl":"https://maps.google.com/?q=Chelsea+Market"},{"id":"nact_12","title":"Greenwich Village Comedy Cellar","category":"Nightlife","location":"Greenwich Village, Manhattan","description":"Wander Washington Square Park, then laugh at surprise drop-in sets from famous comics.","estimatedDuration":"3 hrs","estimatedCost":40,"timeOfDay":"Evening","lat":40.7302,"lng":-74.0005,"googleMapsUrl":"https://maps.google.com/?q=Comedy+Cellar"}]}]'::jsonb,
