m/?q=Metropolitan+Museum+of+Art"},{"id":"nact_6","title":"Jazz Night in Harlem","category":"Nightlife","location":"Harlem, Manhattan","description":"Eat soul food and catch live jazz in the neighborhood that shaped American music.","estimatedDuration":"3 hrs","estimatedCost":55,"timeOfDay":"Evening","lat":40.8116,"lng":-73.9465,"googleMapsUrl":"https://maps.google.com/?q=Minton%27s+Playhouse"}]},{"dayNumber":3,"title":"Lower Manhattan & Brooklyn","activities":[{"id":"nact_7","title":"Statue of Liberty Ferry & Ellis Island","category":"History","location":"Liberty Island, New York","description":"Sail to Lady Liberty and trace immigrant stories at the Ellis Island museum.","estimatedDuration":"4 hrs","estimatedCost":25,"timeOfDay":"Morning","lat":40.6892,"lng":-74.0445,"googleMapsUrl":"https://maps.google.com/?q=Statue+of+Liberty"},{"id":"nact_8","title":"9/11 Memorial & One World Observatory","category":"History","location":"Financial District, Manhattan","description":"Pay respects at the reflecting pools, then ride to the top of the Western Hemisphere’s tallest building.","estimatedDuration":"2.5 hrs","estimatedCost":45,"timeOfDay":"Afternoon","lat":40.7115,"lng":-74.0134,"googleMapsUrl":"https://maps.google.com/?q=9/11+Memorial"},{"id":"nact_9","title":"Brooklyn Bridge Walk & DUMBO Pizza","category":"Food","location":"DUMBO, Brooklyn","description":"Walk the bridge at golden hour and end with coal-fired pizza beside the Manhattan Bridge view.","estimatedDuration":"2.5 hrs","estimatedCost":30,"timeOfDay":"Evening","lat":40.7033,"lng":-73.9881,"googleMapsUrl":"https://maps.google.com/?q=DUMBO+Brooklyn"}]},{"dayNumber":4,"title":"High Line, Chelsea & Village Farewell","activities":[{"id":"nact_10","title":"The High Line Elevated Park","category":"Nature","location":"Chelsea, Manhattan","description":"Stroll a former freight rail line turned garden walkway ending at Hudson Yards’ Vessel.","estimatedDuration":"2 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":40.748,"lng":-74.0048,"googleMapsUrl":"https://maps.google.com/?q=The+High+Line"},{"id":"nact_11","title":"Chelsea Market Food Hall Lunch","category":"Food","location":"Meatpacking District, Manhattan","description":"Graze on lobster rolls, tacos, and fresh-baked brownies in an old Nabisco factory.","estimatedDuration":"1.5 hrs","estimatedCost":30,"timeOfDay":"Afternoon","lat":40.7424,"lng":-74.0061,"googleMapsUrl":"https://maps.google.com/?q=Chelsea+Market"},{"id":"nact_12","title":"Greenwich Village Comedy Cellar","category":"Nightlife","location":"Greenwich Village, Manhattan","description":"Wander Washington Square Park, then laugh at surprise drop-in sets from famous comics.","estimatedDuration":"3 hrs","estimatedCost":40,"timeOfDay":"Evening","lat":40.7302,"lng":-74.0005,"googleMapsUrl":"https://maps.google.com/?q=Comedy+Cellar"}]}]'::jsonb,
