  days = '[{"dayNumber":1,"title":"Arrive in Ubud: Jungle & Monkeys","activities":[{"id":"baact_1","title":"Check in to a Jungle Villa in Ubud","category":"Hotel","location":"Ubud, Bali","description":"Settle into a villa overlooking the Ayung River valley and recover from the flight by the pool.","estimatedDuration":"2 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":-8.5069,"lng":115.2625,"googleMapsUrl":"https://maps.google.com/?q=Ubud"},{"id":"baact_2","title":"Sacred Monkey Forest Sanctuary","category":"Nature","location":"Ubud, Bali","description":"Walk among mossy temples and hundreds of long-tailed macaques in an ancient forest.","estimatedDuration":"1.5 hrs","estimatedCost":6,"timeOfDay":"Afternoon","lat":-8.5188,"lng":115.2585,"googleMapsUrl":"https://maps.google.com/?q=Sacred+Monkey+Forest+Sanctuary"},{"id":"baact_3","title":"Balinese Dance at Ubud Palace & Warung Dinner","category":"Food","location":"Ubud, Bali","description":"Watch a Legong dance in the royal palace courtyard, then dine on babi guling (suckling pig).","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":-8.5069,"lng":115.2624,"googleMapsUrl":"https://maps.google.com/?q=Ubud+Palace"}]},{"dayNumber":2,"title":"Rice Terraces & Water Temples","activities":[{"id":"baact_4","title":"Tegallalang Rice Terraces & Jungle Swing","category":"Photography","location":"Tegallalang, Bali","description":"Hike the sculpted green terraces early and swing out over the valley.","estimatedDuration":"2.5 hrs","estimatedCost":25,"timeOfDay":"Morning","lat":-8.4312,"lng":115.2793,"googleMapsUrl":"https://maps.google.com/?q=Tegallalang+Rice+Terrace"},{"id":"baact_5","title":"Tirta Empul Holy Spring Purification","category":"History","location":"Tampaksiring, Bali","description":"Join locals in a sacred water-blessing ritual beneath carved stone spouts.","estimatedDuration":"2 hrs","estimatedCost":5,"timeOfDay":"Afternoon","lat":-8.4153,"lng":115.3153,"googleMapsUrl":"https://maps.google.com/?q=Tirta+Empul"},{"id":"baact_6","title":"Balinese Massage & Spa Ritual","category":"Luxury","location":"Ubud, Bali","description":"Unwind with a two-hour flower bath and traditional massage for a fraction of Western prices.","estimatedDuration":"2 hrs","estimatedCost":35,"timeOfDay":"Evening","lat":-8.51,"lng":115.263,"googleMapsUrl":"https://maps.google.com/?q=Ubud+Spa"}]},{"dayNumber":3,"title":"Mt. Batur Sunrise Trek","activities":[{"id":"baact_7","title":"Mount Batur Sunrise Volcano Hike","category":"Hiking","location":"Kintamani, Bali","description":"Start at 4am to summit an active volcano and watch the sun rise over Lake Batur and Mt. Agung.","estimatedDuration":"5 hrs","estimatedCost":45,"timeOfDay":"Morning","lat":-8.2421,"lng":115.3751,"googleMapsUrl":"https://maps.google.com/?q=Mount+Batur"},{"id":"baact_8","title":"Natural Hot Springs & Coffee Plantation","category":"Nature","location":"Kintamani, Bali","description":"Soak tired legs in lakeside hot springs and taste Bali coffee at a plantation.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Afternoon","lat":-8.256,"lng":115.4,"googleMapsUrl":"https://maps.google.com/?q=Batur+Natural+Hot+Spring"},{"id":"baact_9","title":"Early Night with Room-Service Nasi Goreng","category":"Food","location":"Ubud, Bali","description":"Recharge after the 3am start with a quiet dinner at the villa.","estimatedDuration":"1.5 hrs","estimatedCost":10,"timeOfDay":"Evening","lat":-8.5069,"lng":115.2625,"googleMapsUrl":"https://maps.google.com/?q=Ubud"}]},{"dayNumber":4,"title":"Waterfalls & Move to the Coast","activities":[{"id":"baact_10","title":"Tibumana & Tukad Cepung Waterfalls","category":"Nature","location":"Bangli, Bali","description":"Swim beneath a jungle waterfall, then see light beams pour into a hidden cave fall.","estimatedDuration":"3 hrs","estimatedCost":5,"timeOfDay":"Morning","lat":-8.443,"lng":115.3655,"googleMapsUrl":"https://maps.google.com/?q=Tukad+Cepung+Waterfall"},{"id":"baact_11","title":"Transfer to Seminyak Beach Hotel","category":"Hotel","location":"Seminyak, Bali","description":"Drive south to the coast and check in near the beach boutiques.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Afternoon","lat":-8.6913,"lng":115.1682,"googleMapsUrl":"https://maps.google.com/?q=Seminyak"},{"id":"baact_12","title":"Tanah Lot Temple Sunset","category":"Photography","location":"Tabanan, Bali","description":"Watch the sun sink behind a sea temple perched on a rock in the crashing surf.","estimatedDuration":"2.5 hrs","estimatedCost":5,"timeOfDay":"Evening","lat":-8.6212,"lng":115.0868,"googleMapsUrl":"https://maps.google.com/?q=Tanah+Lot"}]},{"dayNumber":5,"title":"Uluwatu Cliffs & Kecak Fire Dance","activities":[{"id":"baact_13","title":"Surf Lesson at Kuta Beach","category":"Beach","location":"Kuta, Bali","description":"Catch your first waves on gentle beach breaks with a local instructor.","estimatedDuration":"2 hrs","estimatedCost":30,"timeOfDay":"Morning","lat":-8.718,"lng":115.1686,"googleMapsUrl":"https://maps.google.com/?q=Kuta+Beach"},{"id":"baact_14","title":"Padang Padang & Suluban Hidden Beaches","category":"Beach","location":"Uluwatu, Bali","description":"Climb down through rock crevices to tiny coves with turquoise water.","estimatedDuration":"3 hrs","estimatedCost":3,"timeOfDay":"Afternoon","lat":-8.8106,"lng":115.1032,"googleMapsUrl":"https://maps.google.com/?q=Padang+Padang+Beach"},{"id":"baact_15","title":"Uluwatu Temple Kecak Fire Dance","category":"Festival","location":"Uluwatu, Bali","description":"Watch a hypnotic chanting fire dance on a cliff 70 meters above the ocean at sunset.","estimatedDuration":"2 hrs","estimatedCost":15,"timeOfDay":"Evening","lat":-8.8291,"lng":115.0849,"googleMapsUrl":"https://maps.google.com/?q=Uluwatu+Temple"}]},{"dayNumber":6,"title":"Beach Club Farewell","activities":[{"id":"baact_16","title":"Yoga Class & Smoothie Bowl Brunch","category":"Cafe","location":"Canggu, Bali","description":"Stretch out at an open-air shala, then refuel at one of Canggu’s famous brunch cafés.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Morning","lat":-8.6478,"lng":115.1385,"googleMapsUrl":"https://maps.google.com/?q=Canggu"},{"id":"baact_17","title":"Seminyak Boutiques & Beach Walk","category":"Shopping","location":"Seminyak, Bali","description":"Shop for linen, rattan bags, and silver jewelry along Jalan Kayu Aya.","estimatedDuration":"2.5 hrs","estimatedCost":40,"timeOfDay":"Afternoon","lat":-8.6845,"lng":115.161,"googleMapsUrl":"https://maps.google.com/?q=Jalan+Kayu+Aya"},{"id":"baact_18","title":"Sunset Cocktails at Potato Head Beach Club","category":"Nightlife","location":"Seminyak, Bali","description":"Toast your trip poolside as fire-red skies fade over the Indian Ocean.","estimatedDuration":"3 hrs","estimatedCost":50,"timeOfDay":"Evening","lat":-8.6795,"lng":115.153,"googleMapsUrl":"https://maps.google.com/?q=Potato+Head+Beach+Club"}]}]'::jsonb,
