-- 5 Days in Seoul: Palaces, K-Culture & Night Markets
update public.travel_plans set
  destination = 'Seoul',
  country = 'South Korea',
  flag_emoji = '🇰🇷',
  cover_image = 'https://images.unsplash.com/photo-1517154421773-0529f29ea451?auto=format&fit=crop&w=1200&q=80',
  summary = 'Wear a hanbok to Gyeongbokgung, sizzle Korean BBQ, shop Myeongdong skincare, peer into North Korea at the DMZ, and graze through Gwangjang Market after dark.',
  duration_days = 5,
  season = 'Autumn',
  preferences = '["City","Food","History","Shopping","Nightlife"]'::jsonb,
  companion_style = 'Solo',
  estimated_cost_usd = 1050,
  transportation = 'Seoul Metro with T-money card',
  weather_forecast = 'Crisp Autumn 17°C (63°F), clear skies & red maple leaves',
  packing_list = '[{"id":"sep1","category":"Essentials","item":"T-money transit card","packed":true},{"id":"sep2","category":"Electronics","item":"Naver Map & Papago translator downloaded","packed":true},{"id":"sep3","category":"Documents","item":"Passport for the DMZ tour (mandatory)","packed":false},{"id":"sep4","category":"Essentials","item":"Extra suitcase space for Korean skincare","packed":false}]'::jsonb,
  days = '[{"dayNumber":1,"title":"Royal Palaces & Bukchon Hanok Village","activities":[{"id":"seact_1","title":"Gyeongbokgung Palace in a Rented Hanbok","category":"History","location":"Jongno, Seoul","description":"Rent traditional dress (free palace entry!) and watch the royal guard changing ceremony.","estimatedDuration":"3 hrs","estimatedCost":20,"timeOfDay":"Morning","lat":37.5796,"lng":126.977,"googleMapsUrl":"https://maps.google.com/?q=Gyeongbokgung+Palace"},{"id":"seact_2","title":"Bukchon Hanok Village & Insadong Tea House","category":"Hidden Gems","location":"Jongno, Seoul","description":"Walk hillside lanes of tiled-roof homes, then sip jujube tea in an Insadong tea house.","estimatedDuration":"2.5 hrs","estimatedCost":12,"timeOfDay":"Afternoon","lat":37.5826,"lng":126.9831,"googleMapsUrl":"https://maps.google.com/?q=Bukchon+Hanok+Village"},{"id":"seact_3","title":"Gwangjang Market Night Food","category":"Food","location":"Jongno, Seoul","description":"Eat crispy bindaetteok mung-bean pancakes and live octopus at Seoul’s oldest market.","estimatedDuration":"2 hrs","estimatedCost":18,"timeOfDay":"Evening","lat":37.5701,"lng":126.9996,"googleMapsUrl":"https://maps.google.com/?q=Gwangjang+Market"}]},{"dayNumber":2,"title":"Myeongdong, N Seoul Tower & K-BBQ","activities":[{"id":"seact_4","title":"Changdeokgung Secret Garden Tour","category":"Nature","location":"Jongno, Seoul","description":"Join a guided tour of the UNESCO-listed royal garden with lotus ponds and pavilions.","estimatedDuration":"2 hrs","estimatedCost":8,"timeOfDay":"Morning","lat":37.5794,"lng":126.991,"googleMapsUrl":"https://maps.google.com/?q=Changdeokgung"},{"id":"seact_5","title":"Myeongdong Skincare Shopping & Street Snacks","category":"Shopping","location":"Jung-gu, Seoul","description":"Stock up on sheet masks and snack on egg bread and tornado potatoes.","estimatedDuration":"2.5 hrs","estimatedCost":40,"timeOfDay":"Afternoon","lat":37.5636,"lng":126.9827,"googleMapsUrl":"https://maps.google.com/?q=Myeongdong"},{"id":"seact_6","title":"N Seoul Tower & Korean BBQ Dinner","category":"City","location":"Namsan, Seoul","description":"Ride the cable car up Namsan for city lights, then grill samgyeopsal pork belly at your table.","estimatedDuration":"3 hrs","estimatedCost":45,"timeOfDay":"Evening","lat":37.5512,"lng":126.9882,"googleMapsUrl":"https://maps.google.com/?q=N+Seoul+Tower"}]},{"dayNumber":3,"title":"DMZ Tour & Hongdae Nightlife","activities":[{"id":"seact_7","title":"DMZ & Third Infiltration Tunnel Tour","category":"History","location":"Paju, Gyeonggi-do","description":"Look across into North Korea from Dora Observatory and walk a secret invasion tunnel.","estimatedDuration":"5 hrs","estimatedCost":70,"timeOfDay":"Morning","lat":37.9165,"lng":126.699,"googleMapsUrl":"https://maps.google.com/?q=Third+Tunnel+of+Aggression"},{"id":"seact_8","title":"Hongdae Indie Cafés & Street Buskers","category":"Cafe","location":"Mapo-gu, Seoul","description":"Recover in a quirky themed café and watch K-pop dance crews perform in the street.","estimatedDuration":"2 hrs","estimatedCost":15,"timeOfDay":"Afternoon","lat":37.5563,"lng":126.9236,"googleMapsUrl":"https://maps.google.com/?q=Hongdae"},{"id":"seact_9","title":"Hongdae Clubs & Noraebang Karaoke","category":"Nightlife","location":"Mapo-gu, Seoul","description":"Belt out K-pop in a private karaoke room, then hit the university district’s clubs.","estimatedDuration":"4 hrs","estimatedCost":40,"timeOfDay":"Evening","lat":37.555,"lng":126.922,"googleMapsUrl":"https://maps.google.com/?q=Hongdae+Club+Street"}]},{"dayNumber":4,"title":"Gangnam Glamour & Han River","activities":[{"id":"seact_10","title":"Starfield Library at COEX Mall","category":"Architecture","location":"Gangnam, Seoul","description":"Snap photos beneath 13-meter towering bookshelves in this Instagram-famous library.","estimatedDuration":"1.5 hrs","estimatedCost":0,"timeOfDay":"Morning","lat":37.51,"lng":127.06,"googleMapsUrl":"https://maps.google.com/?q=Starfield+Library"},{"id":"seact_11","title":"Lotte World Tower Seoul Sky","category":"City","location":"Songpa-gu, Seoul","description":"Step onto the glass floor 500 meters up the world’s sixth-tallest building.","estimatedDuration":"2 hrs","estimatedCost":25,"timeOfDay":"Afternoon","lat":37.5126,"lng":127.1025,"googleMapsUrl":"https://maps.google.com/?q=Lotte+World+Tower"},{"id":"seact_12","title":"Han River Picnic & Banpo Rainbow Fountain","category":"Romantic","location":"Banpo Hangang Park, Seoul","description":"Order fried chicken delivered to the riverbank and watch the bridge’s rainbow fountain show.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":37.51,"lng":126.996,"googleMapsUrl":"https://maps.google.com/?q=Banpo+Bridge+Rainbow+Fountain"}]},{"dayNumber":5,"title":"Ikseon-dong & Farewell Feast","activities":[{"id":"seact_13","title":"Ikseon-dong Hanok Café Alleys","category":"Cafe","location":"Jongno, Seoul","description":"Brunch in century-old hanok houses converted into trendy bakeries and boutiques.","estimatedDuration":"2 hrs","estimatedCost":18,"timeOfDay":"Morning","lat":37.5744,"lng":126.9897,"googleMapsUrl":"https://maps.google.com/?q=Ikseon-dong"},{"id":"seact_14","title":"Dongdaemun Design Plaza","category":"Architecture","location":"Jung-gu, Seoul","description":"Explore Zaha Hadid’s futuristic silver-curved landmark and its design exhibitions.","estimatedDuration":"2 hrs","estimatedCost":10,"timeOfDay":"Afternoon","lat":37.5665,"lng":127.0092,"googleMapsUrl":"https://maps.google.com/?q=Dongdaemun+Design+Plaza"},{"id":"seact_15","title":"Cheonggyecheon Stream Walk & Hanjeongsik Dinner","category":"Food","location":"Jung-gu, Seoul","description":"Stroll the lantern-lit urban stream, then feast on a 20-dish royal-style set dinner.","estimatedDuration":"3 hrs","estimatedCost":55,"timeOfDay":"Evening","lat":37.5691,"lng":126.9786,"googleMapsUrl":"https://maps.google.com/?q=Cheonggyecheon"}]}]'::jsonb,
