.com/?q=Starfield+Library"},{"id":"seact_11","title":"Lotte World Tower Seoul Sky","category":"City","location":"Songpa-gu, Seoul","description":"Step onto the glass floor 500 meters up the world’s sixth-tallest building.","estimatedDuration":"2 hrs","estimatedCost":25,"timeOfDay":"Afternoon","lat":37.5126,"lng":127.1025,"googleMapsUrl":"https://maps.google.com/?q=Lotte+World+Tower"},{"id":"seact_12","title":"Han River Picnic & Banpo Rainbow Fountain","category":"Romantic","location":"Banpo Hangang Park, Seoul","description":"Order fried chicken delivered to the riverbank and watch the bridge’s rainbow fountain show.","estimatedDuration":"2.5 hrs","estimatedCost":20,"timeOfDay":"Evening","lat":37.51,"lng":126.996,"googleMapsUrl":"https://maps.google.com/?q=Banpo+Bridge+Rainbow+Fountain"}]},{"dayNumber":5,"title":"Ikseon-dong & Farewell Feast","activities":[{"id":"seact_13","title":"Ikseon-dong Hanok Café Alleys","category":"Cafe","location":"Jongno, Seoul","description":"Brunch in century-old hanok houses converted into trendy bakeries and boutiques.","estimatedDuration":"2 hrs","estimatedCost":18,"timeOfDay":"Morning","lat":37.5744,"lng":126.9897,"googleMapsUrl":"https://maps.google.com/?q=Ikseon-dong"},{"id":"seact_14","title":"Dongdaemun Design Plaza","category":"Architecture","location":"Jung-gu, Seoul","description":"Explore Zaha Hadid’s futuristic silver-curved landmark and its design exhibitions.","estimatedDuration":"2 hrs","estimatedCost":10,"timeOfDay":"Afternoon","lat":37.5665,"lng":127.0092,"googleMapsUrl":"https://maps.google.com/?q=Dongdaemun+Design+Plaza"},{"id":"seact_15","title":"Cheonggyecheon Stream Walk & Hanjeongsik Dinner","category":"Food","location":"Jung-gu, Seoul","description":"Stroll the lantern-lit urban stream, then feast on a 20-dish royal-style set dinner.","estimatedDuration":"3 hrs","estimatedCost":55,"timeOfDay":"Evening","lat":37.5691,"lng":126.9786,"googleMapsUrl":"https://maps.google.com/?q=Cheonggyecheon"}]}]'::jsonb,
